function removeDuplicateLetters(s) {
  // Build the answer one letter at a time: take the smallest still-needed letter whose
  // first occurrence from here leaves every other needed letter somewhere after it.
  const needed = new Set(s);
  let result = '';
  let start = 0;
  while (needed.size > 0) {
    const letters = [...needed].sort();
    for (const c of letters) {
      const pos = s.indexOf(c, start);
      const after = new Set(s.slice(pos + 1));
      if (letters.every(x => x === c || after.has(x))) {
        result += c;
        needed.delete(c);
        start = pos + 1;
        break;
      }
    }
  }
  return result;
}

