function generate(rand, size) {
  const pick = k => Math.floor(rand() * k);
  const alphabet = 'abcdefghijklmnopqrstuvwxyz';
  if (size === 'large') {
    const k = rand() < 0.3 ? 3 + pick(6) : 26;
    const length = 5000 + pick(5001);
    const shift = pick(26 - k + 1);
    let s = '';
    for (let i = 0; i < length; i++) s += alphabet[shift + pick(k)];
    return [s];
  }
  const k = 1 + pick(6);
  const shift = pick(26 - k + 1);
  const length = 1 + pick(12);
  let s = '';
  for (let i = 0; i < length; i++) s += alphabet[shift + pick(k)];
  return [s];
}
